function welcome(){app.innerHTML=`<section class="titleScreen"><div class="titleShade"></div><img class="titleCharacter" src="assets/aobee-official.webp" alt="あおびー"><div class="titleCopy"><span class="titleBadge">SLG · 開発中 v${VERSION}</span><p class="eyebrow">六つの旗が、乱世に立つ。</p><h1><span>あおびーの</span><strong>野望</strong></h1><p class="titleSubtitle">～ 七色戦国記 ～</p><p class="titleLead">国を育て、人を任せ、盟を結ぶ。<br>あなたの一手で、この国の明日が変わる。</p><div class="titleActions"><button class="primary" id="newCampaign">はじめから</button><button id="continue">続きから</button><button id="titleHelp">遊び方</button><button id="titleImport">記録を読み込む</button></div><p class="titleStatus">12城・6勢力・54武将 / 内政・外交・8×6合戦を試遊できます<br>進軍・撤退・占領に対応 / 武将の関係・連鎖ドラマ・動的派閥に対応</p><a class="portalLink" href="../../index.html#games">ゲームポータルへ ↗</a></div><span class="titleEdition">戦国戦略シミュレーション / Ver.1.2設計準拠</span></section>`;$('#newCampaign').onclick=()=>factionSelect();$('#continue').onclick=()=>load();$('#titleImport').onclick=()=>$('#importFile').click();$('#titleHelp').onclick=()=>modal('<h2>国づくりの始め方</h2><p>①「はじめから」で大名家を選ぶ。<br>② 地図の自城を選び、内政の担当武将を予約。<br>③ 外交で他家に贈物を送り、関係30以上で同盟を交渉。<br>④「次月へ」で命令と収支を処理。</p><p>城ごとに月2命令、武将ごとに1任務。外交と内政で共有します。予約は月末まで取消可能です。</p><p>他家の同盟提案は外交画面で受諾・辞退できます。保存は月末自動、手動3枠、JSON書出しに対応。</p>');}
function render(){
 const own=state.castles.filter(c=>c.ownerFactionId===state.playerFactionId),f=faction(state.playerFactionId);
 app.innerHTML=`<div class="shell"><header class="topbar"><span class="brand">あおびーの野望 <small class="muted">七色戦国記</small></span><span class="time">第${state.year}年 ${state.month}月</span><div class="resources"><div><span>${e(f.name)}</span><b>${own.length}城 / ${state.officers.filter(o=>o.factionId===f.id).length}武将</b></div><div><span>領内の金</span><b>${num(own.reduce((a,c)=>a+c.gold,0))}</b></div><div><span>領内の兵糧</span><b>${num(own.reduce((a,c)=>a+c.food,0))}</b></div></div><button class="primary" id="next">次月へ</button></header><div class="workspace ${mapExpanded?'mapExpanded':''}"><section class="mapPane" aria-label="全国マップ"><div class="mapTitle"><span class="eyebrow">${state.factions.filter(f=>W.aliveFaction(state,f.id)).length}勢力の興亡</span><h2>全国図</h2><small>城を選択 / 街道は双方向</small></div><svg id="map" viewBox="0 0 1000 1000" aria-label="12城と16街道"></svg><div class="mapTools"><button id="zoomIn" aria-label="地図を拡大">＋</button><button id="zoomOut" aria-label="地図を縮小">−</button><button id="resetMap">全図</button><button id="mapExpand" aria-pressed="${mapExpanded}">${mapExpanded?'城の情報へ':'地図を広く'}</button></div><div class="mapLegend">ドラッグで移動 / ピンチで拡大</div></section><aside class="side" id="side"></aside></div><footer class="bottom"><nav>${['内政','人材','出来事','報告','外交','軍事'].map(x=>`<button data-tab="${x}" ${tab===x?'class="primary"':''}>${x==='出来事'&&(state.events.pending||state.personnel.drama.pending||state.personnel.chains.pending)?'出来事 1':x}</button>`).join('')}</nav><span class="phase">開発中 / 内政・外交・合戦</span><button id="saveMenu">記録・設定</button></footer></div>`;
 drawMap();drawSide();setupMap();$('#mapExpand').onclick=()=>{mapExpanded=!mapExpanded;zoom=1;camera={x:0,y:0};render();};$('#next').onclick=confirmMonth;$('#saveMenu').onclick=saveMenu;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='出来事'){showEvents();return;}if(b.dataset.tab==='外交'){openDiplomacy();return;}if(b.dataset.tab==='軍事'){openMilitary();return;}tab=b.dataset.tab;if(mapExpanded){mapExpanded=false;zoom=1;camera={x:0,y:0};render();}if(tab==='報告')showReport();else render();});
}
function drawMap(){const svg=$('#map'),rect=svg.getBoundingClientRect(),ratio=Math.max(.55,Math.min(3,rect.width/Math.max(1,rect.height))),sx=Math.max(1,ratio),sy=Math.max(1,1/ratio),scale=Math.min(rect.width/(1000*sx),rect.height/(1000*sy)),pin=Math.max(27,16/scale),hit=Math.max(64,22/scale),font=Math.max(19,16/scale);svg.setAttribute('viewBox',`0 0 ${1000*sx} ${1000*sy}`);svg.innerHTML=`<defs><linearGradient id="landColor" x2="0.4" y2="1"><stop stop-color="#799878"/><stop offset=".55" stop-color="#426b59"/><stop offset="1" stop-color="#274f49"/></linearGradient><pattern id="sea" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M0 20q9-5 18 0t18 0" fill="none" stroke="#aac9c4" stroke-opacity=".04"/></pattern></defs><rect width="${1000*sx}" height="${1000*sy}" fill="url(#sea)"/><g id="world" transform="translate(${camera.x} ${camera.y}) scale(${zoom})"><g class="terrain" transform="scale(${sx} ${sy})"><path class="land" d="M130 62 Q210 35 281 78 L410 61 Q480 42 533 80 L692 40 775 94 802 175 742 225 640 210 578 268 667 299 815 260 877 340 859 448 791 486 807 575 757 650 825 689 916 719 945 812 870 906 748 946 652 909 531 925 460 859 463 773 398 728 334 676 213 695 116 642 111 549 160 487 103 426 105 323 151 258 111 181Z"/><path class="contour" d="M165 100 Q400 165 700 95M136 370Q400 315 822 365M166 618Q440 570 737 613M504 840Q720 759 872 801M189 158Q251 365 195 587M450 165Q353 390 514 681"/><g opacity=".3" fill="#c2c8a0"><path d="M294 245l25-48 26 48-20-15-9 12-7-14ZM610 485l24-48 25 48-21-13-9 13-4-15ZM355 490l20-40 23 40-17-10-6 10-5-10Z"/></g><path class="river" d="M420 110 Q490 220 410 330 T470 550 Q560 640 535 820"/>${state.castles.map(c=>`<circle cx="${c.x}" cy="${c.y}" r="95" fill="${color(c.ownerFactionId)}" opacity=".10" pointer-events="none"/>`).join('')}${M.roads.map(r=>{const a=state.castles.find(c=>c.id===r.fromCastleId),b=state.castles.find(c=>c.id===r.toCastleId);return `<line class="road ${[a.id,b.id].includes(selected)?'active':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`;}).join('')}</g>${state.castles.map(c=>{const i=M.factions.findIndex(f=>f.id===c.ownerFactionId);return `<g class="castle ${selected===c.id?'selected':''}" data-castle="${c.id}" role="button" tabindex="0" aria-label="${e(c.name)} ${e(faction(c.ownerFactionId).name)}" style="--color:${color(c.ownerFactionId)}" transform="translate(${c.x*sx} ${c.y*sy})"><circle class="target" r="${hit}"/><circle class="pin" r="${pin}"/><g class="castleIcon" transform="scale(${pin/26})"><path d="M-21 2L0-10 21 2H13V18H-13V2ZM-16-6L0-18 16-6H9V1H-9V-6Z"/><path class="castleGate" d="M-3 18V9H3V18"/><path class="castleFlag" d="M0-18V-29L12-25 0-21"/></g><text style="font-size:${font}px" text-anchor="middle" y="${pin+font*1.2}">${e(c.name)}</text></g>`;}).join('')}</g>`;
 svg.querySelectorAll('[data-castle]').forEach(n=>{n.onclick=()=>selectCastle(n.dataset.castle);n.onkeydown=ev=>{if(['Enter',' '].includes(ev.key)){ev.preventDefault();selectCastle(n.dataset.castle);}};});}
function selectCastle(id){selected=id;if(mapExpanded){mapExpanded=false;zoom=1;camera={x:0,y:0};render();}else{drawMap();drawSide();}}
function drawSide(){const c=state.castles.find(c=>c.id===selected),own=c.ownerFactionId===state.playerFactionId,os=state.officers.filter(o=>o.locationCastleId===c.id),qs=state.commands.filter(q=>q.castleId===c.id);
 $('#side').innerHTML=`<div class="castleHeading"><span class="castleCrest" style="--crest:${color(c.ownerFactionId)}">${marks[M.factions.findIndex(f=>f.id===c.ownerFactionId)]||'独'}</span><div><div class="region">${e(c.region)} / ${own?'自領':'他家領'}</div><h2>${e(c.name)}</h2><div class="owner" style="color:${color(c.ownerFactionId)}">${e(faction(c.ownerFactionId).name)}</div></div></div><div class="stats">${[['gold','金'],['food','兵糧'],['troops','兵数'],['publicOrder','民心'],['farm','農業'],['commerce','商業'],['defense','城防']].map(([k,label])=>`<div class="stat"><span>${label}</span><b>${num(c[k])}</b>${['farm','commerce','defense','publicOrder'].includes(k)?`<div class="bar"><i style="width:${c[k]}%"></i></div>`:''}</div>`).join('')}</div>${tab==='人材'?`<div class="personnelActions"><button id="dramaOpen">家臣の便り</button><button id="relationshipOpen">関係・派閥</button><button id="biographyOpen">武将列伝を読む</button><button id="personnelOpen">探索・登用を開く</button><button id="loyaltyOpen">忠誠・褒賞を開く</button><button id="allegianceOpen">引き抜き・家臣の予兆${([...state.personnel.unrest.pending,...state.personnel.independence.pending].some(p=>p.factionId===state.playerFactionId)||state.personnel.intrigue.pending.some(p=>p.targetFactionId===state.playerFactionId)||state.castles.some(c=>c.ownerFactionId===state.playerFactionId&&YabouInsiders.threatened(state,state.playerFactionId,c.id)))?' ！':''}</button></div><h3>配置武将</h3>${os.map(o=>`<div class="officer"><div>${e(o.name)}<br><span>${e(o.role)} / 政務 ${o.stats.politics} / 忠誠 ${o.loyalty}（${E.loyaltyLabel(o.loyalty)}）</span></div><span>${state.commands.some(q=>q.officerId===o.id)?'任務予約済':'待機'}</span></div>`).join('')}`:`<h3>今月の命令 ${qs.length+state.diplomacyCommands.filter(q=>q.castleId===c.id).length+W.count(state,c.id)}/2</h3>${own?`<div class="commands">${E.types.filter(t=>!['scheme','counterplot','mediate'].includes(t)).map(t=>`<button data-command="${t}">${E.labels[t]}<br><small>金${t==='search'?'100〜500':t==='hire'?'0〜300':['reward','poach'].includes(t)?'100〜500':R.commands[t].cost.gold}${t==='recruit'?'・糧50':''}</small></button>`).join('')}</div>`:'<p class="muted">他家の城に内政命令は出せません。</p>'}${qs.map((q,i)=>`<div class="queue">${e(q.type==='scheme'?YabouIntrigue.labels[q.kind]:E.labels[q.type])}${q.targetId?'：'+e(state.officers.find(o=>o.id===q.targetId)?.name||''):''}${q.targetCastleId?' / '+e(state.castles.find(c=>c.id===q.targetCastleId)?.name||''):''}${['reward','poach'].includes(q.type)?' / 金'+q.offer:''}<button data-cancel="${i}">取消</button><br><span class="muted">${e(state.officers.find(o=>o.id===q.officerId).name)}が担当</span></div>`).join('')}<h3>月次見込み</h3><p class="muted"><small>金 +${Math.floor(c.commerce*1.5*(faction(c.ownerFactionId).trait==='commerce'?1.1:1))} / 兵糧 −${Math.ceil(c.troops/100)}<br>9月に農業値に応じて収穫。予約施策の効果は未反映。</small></p><h3>配置武将</h3><p><small>${os.map(o=>e(o.name)).join('・')}</small></p>`}`;
 if($('#dramaOpen'))$('#dramaOpen').onclick=dramaDialog;if($('#relationshipOpen'))$('#relationshipOpen').onclick=()=>relationshipsDialog();if($('#biographyOpen'))$('#biographyOpen').onclick=()=>biographyDialog();if($('#personnelOpen'))$('#personnelOpen').onclick=personnelDialog;if($('#loyaltyOpen'))$('#loyaltyOpen').onclick=loyaltyDialog;if($('#allegianceOpen'))$('#allegianceOpen').onclick=allegianceDialog;document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>commandDialog(b.dataset.command,c));document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const q=qs[Number(b.dataset.cancel)];state={...state,commands:state.commands.filter(x=>x!==q)};render();notify('予約を取り消しました');});}
function relationshipsDialog(id,scope='local'){
 const P=YabouRelationships,own=state.officers.filter(o=>o.factionId===state.playerFactionId),o=own.find(o=>o.id===id)||own.find(o=>o.locationCastleId===selected)||own[0];
 if(!o){modal('<h2>武将の関係</h2><p>自家に武将がいません。</p>');return;}
 const visible=state.officers.filter(x=>x.id!==o.id&&(x.factionId||state.personnel.known[state.playerFactionId]?.includes(x.id))),visibleIds=new Set(visible.map(x=>x.id));
 const peers=visible.filter(x=>scope==='all'||(scope==='local'?o.locationCastleId&&x.locationCastleId===o.locationCastleId:x.id!==o.id&&(E.bond(state,o.id,x.id)!==0||P.tags(state,o.id,x.id).length))).sort((a,b)=>Math.abs(E.bond(state,o.id,b.id))-Math.abs(E.bond(state,o.id,a.id))||a.id.localeCompare(b.id));
 const logs=state.personnel.relationships.log.filter(x=>x.a===o.id&&visibleIds.has(x.b)||x.b===o.id&&visibleIds.has(x.a)).slice(-8).reverse();
 modal('<section class="relationshipScreen"><span class="eyebrow">RETAINERS & BONDS</span><div class="relationHeading"><h2>武将の関係</h2><button id="campsOpen">派閥を見る</button></div><div class="relationshipControls"><label>自家武将<select id="relationshipOfficer">'+own.map(x=>'<option value="'+x.id+'" '+(x.id===o.id?'selected':'')+'>'+e(x.name)+'</option>').join('')+'</select></label><label>表示<select id="relationshipScope">'+[['local','同じ城'],['known','関わりのある武将'],['all','判明している全武将']].map(([v,t])=>'<option value="'+v+'" '+(scope===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><p class="relationshipHint">武将同士の関係 −100〜＋100。主君への忠誠とは別に記録します。</p><div class="relationshipList">'+(peers.map(x=>{const value=E.bond(state,o.id,x.id),tags=P.tags(state,o.id,x.id);return '<article class="relationshipRow"><div><strong>'+e(x.name)+'</strong><small>'+e(faction(x.factionId)?.name||'浪人')+' / '+e(state.castles.find(c=>c.id===x.locationCastleId)?.name||'所在不明')+'</small><div class="relationshipTags">'+tags.map(t=>'<span>'+P.tagNames[t]+'</span>').join('')+'</div></div><div><b class="relationshipValue '+(value<0?'negative':'')+'">'+(value>0?'+':'')+value+'</b> <small>'+P.label(value)+'</small><div class="relationshipBar" aria-hidden="true"><i style="left:'+(value<0?50+value/2:50)+'%;width:'+Math.abs(value)/2+'%;background:'+(value<0?'#e0a478':'#9dcbb7')+'"></i></div></div></article>';}).join('')||'<p class="notice">この条件に合う武将はいません。表示を切り替えて確認できます。</p>')+'</div><details class="relationshipRecent"><summary>関係値と交流のルール</summary><p class="relationshipHint">関係 −100〜＋100。同じ城で3か月ごとに交流し、相性により±1。共闘した武将同士は＋3。褒賞・イベントの関係も引き継ぎます。</p><p class="muted relationshipHint">友情：＋40以上／ライバル：−40以下／仇敵：−70以下。物語で結ばれた師弟・血縁などのタグは数値と別に保持します。</p></details><details class="relationshipRecent"><summary>最近の交流記録（最新8件）</summary>'+ (logs.map(x=>{const target=state.officers.find(t=>t.id===(x.a===o.id?x.b:x.a));return '<p>第'+(Math.floor((x.turn-1)/12)+1)+'年 '+((x.turn-1)%12+1)+'月 / '+e(target.name)+'：'+(x.kind==='cofight'?'共闘':x.kind==='drama'?'家臣ドラマ':x.kind==='chain'?'連鎖イベント':'同じ城での交流')+' '+(x.delta>0?'+':'')+x.delta+'（'+x.before+'→'+x.after+'）</p>';}).join('')||'<p>交流の記録はまだありません。</p>')+'</details><button id="relationshipBiography">'+e(o.name)+'の列伝</button></section>');
 $('#campsOpen').onclick=()=>campsDialog(o.id);$('#relationshipOfficer').onchange=ev=>relationshipsDialog(ev.target.value,scope);$('#relationshipScope').onchange=ev=>relationshipsDialog(o.id,ev.target.value);$('#relationshipBiography').onclick=()=>biographyDialog(o.id);
}
function campsDialog(id,filter='all'){
 const F=YabouCamps,summary=F.summary(state,state.playerFactionId),members=state.officers.filter(o=>o.status==='active'&&o.factionId===state.playerFactionId&&o.role!=='大名'),shown=members.filter(o=>filter==='all'||summary.records.get(o.id).camp===filter),o=shown.find(o=>o.id===id)||shown[0],r=o?summary.records.get(o.id):null,date=t=>'第'+(Math.floor((t-1)/12)+1)+'年 '+((t-1)%12+1)+'月';
 modal('<section class="campScreen"><h2>派閥と国中の関係</h2><div class="campLayout"><div class="campOverview"><button id="campUnrest">城内の対立・仲裁</button><div class="campCards">'+summary.groups.filter(g=>g.camp!=='neutral').map(g=>'<article class="campCard '+g.camp+'"><strong>'+F.labels[g.camp]+'</strong><b>'+g.members.length+'人</b><small>'+(g.leaderId?'中心：'+e(state.officers.find(o=>o.id===g.leaderId).name):g.members.length?'一人の傾向':'現在なし')+'</small><small>'+(g.cohesion===null?'内部の関係記録なし':'内部関係 '+(g.cohesion>0?'+':'')+g.cohesion+' / '+g.links+'組')+'</small></article>').join('')+'</div><p class="campHint">無所属 '+summary.groups.find(g=>g.camp==='neutral').members.length+'人 / 派閥間の強い対立 '+summary.conflicts+'組'+(summary.conflicts?'（平均 '+summary.tension+'）':'')+'</p></div><div class="campDetail"><div class="campControls"><label>傾向<select id="campFilter">'+[['all','すべて'],...Object.entries(F.labels).filter(([v])=>v!=='none')].map(([v,t])=>'<option value="'+v+'" '+(filter===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>家臣<select id="campOfficer">'+shown.map(x=>'<option value="'+x.id+'" '+(x.id===o?.id?'selected':'')+'>'+e(x.name)+'</option>').join('')+'</select></label></div>'+(o?'<section class="campProfile"><h3>'+e(o.name)+' <span class="campBadge '+r.camp+'">'+F.labels[r.camp]+'</span></h3><p class="campHint">'+e(state.castles.find(c=>c.id===o.locationCastleId).name)+' / 忠誠 '+o.loyalty+' / '+date(r.sinceTurn)+'から</p><div class="campScores">'+F.types.map(k=>'<div><span>'+F.labels[k]+'</span><b>'+r.scores[k]+'</b><div class="bar"><i style="width:'+r.scores[k]+'%"></i></div></div>').join('')+'</div><details class="campReasons"><summary>この傾向になった理由</summary>'+r.reasons.map(x=>'<p>'+e(x)+'</p>').join('')+'</details><div class="sectionButtons"><button id="campRelations">武将の関係</button><button id="campReward">忠誠・褒賞</button><button id="campBiography">武将列伝</button></div></section>':'<p class="notice">この傾向に当てはまる現役家臣はいません。</p>')+'</div></div><details class="campRules"><summary>派閥の変化と介入</summary><p>所属国とは別の国内の傾向です。月次進行と選択後に見直し、能力・野心・義理・忠誠、直近6か月の任務や共闘、同じ城の親しい家臣を反映します。各数値は0〜100の傾向点です。50点以上で参加し、現在の点が45以上・他の傾向との差が8未満なら所属を維持します。</p><p>武断派は稽古や軍略、文治派は交流や推薦、独立派は密談や直訴などの便りが出やすくなります。対象条件と発生間隔は従来どおりです。独立派というだけで出奔することはなく、危険な家臣は「引き抜き・家臣の予兆」で確認し、褒賞などで介入できます。</p><p>中心人物は同じ傾向の家臣が2人以上いる場合の目安。内部関係は記録がある組だけの平均です。</p></details><details><summary>最近の変化（最新12件）</summary>'+state.personnel.camps.log.filter(h=>h.fromFactionId===state.playerFactionId||h.toFactionId===state.playerFactionId).slice(-12).reverse().map(h=>'<p>'+date(h.turn)+' / '+e(state.officers.find(o=>o.id===h.officerId).name)+'：'+F.labels[h.from]+' → '+F.labels[h.to]+'</p>').join('')+'</details></section>');
 $('#campUnrest').onclick=unrestDialog;$('#campFilter').onchange=ev=>campsDialog(id,ev.target.value);$('#campOfficer').onchange=ev=>campsDialog(ev.target.value,filter);if(o){$('#campRelations').onclick=()=>relationshipsDialog(o.id);$('#campBiography').onclick=()=>biographyDialog(o.id);$('#campReward').onclick=()=>{selected=o.locationCastleId;render();loyaltyDialog();};}
}
function biographyDialog(id){
 const visible=state.officers.filter(o=>o.factionId||state.personnel.known[state.playerFactionId]?.includes(o.id));const o=visible.find(o=>o.id===id)||visible.find(o=>o.factionId===state.playerFactionId)||visible[0],b=state.biography.officers[o.id];
 modal('<section class="biographyScreen"><h2>武将列伝</h2><label>武将 <select id="biographyOfficer">'+visible.map(x=>'<option value="'+x.id+'" '+(x.id===o.id?'selected':'')+'>'+e(x.name)+' / '+e(faction(x.factionId)?.name||'浪人')+'</option>').join('')+'</select></label><h3>'+e(o.name)+'</h3><p>'+(o.species?e(o.species)+' / ':'')+e(o.role)+' / '+e(faction(o.factionId)?.name||'浪人')+' / 忠誠 '+o.loyalty+'</p><p>統 '+o.stats.leadership+'・武 '+o.stats.valor+'・知 '+o.stats.intellect+'・政 '+o.stats.politics+'・魅 '+o.stats.charisma+'</p><p class="muted">記録は各武将の最新80件。旧セーブに残っていない過去の経歴は補完しません。</p>'+(b.entries.length?'<ol class="chronicle">'+[...b.entries].reverse().map(x=>'<li><small>第'+(Math.floor((x.turn-1)/12)+1)+'年 '+((x.turn-1)%12+1)+'月</small><p>'+e(x.text)+'</p></li>').join('')+'</ol>':'<p class="notice">この記録での重要な経歴はまだありません。</p>')+'</section>');$('#biographyOfficer').onchange=ev=>biographyDialog(ev.target.value);
}
function commandDialog(type,c){if(type==='mediate'){unrestDialog();return;}if(['scheme','counterplot'].includes(type)){intrigueDialog();return;}if(type==='poach'){allegianceDialog();return;}if(type==='reward'){loyaltyDialog();return;}if(['search','hire'].includes(type)){personnelDialog();return;}const r=R.commands[type],os=state.officers.filter(o=>o.locationCastleId===c.id),effects={cultivate:'農業 +5（上限100）',commerce:'商業 +5（上限100）',fortify:'城防 +5（上限100）',recruit:'兵数 +200 / 民心 −3（下限0）'};
 modal(`<h2>${E.labels[type]}</h2><p>${e(c.name)} / 金${r.cost.gold}${r.cost.food?'・兵糧'+r.cost.food:''}</p><div class="notice">${effects[type]}<br>担当武将を選ぶと予約します。月末まで取消可能です。<br>この段階では武将能力による施策量の補正はありません。</div>${os.map(o=>{const q={type,castleId:c.id,officerId:o.id,factionId:state.playerFactionId},reason=E.canIssueCommand(state,q,R);return `<div><button data-assign="${o.id}" ${reason?'disabled':''}>${e(o.name)}で予約</button><small class="muted">${reason?e(reason):'政務 '+o.stats.politics}</small></div>`;}).join('')}`);
 document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{try{state=E.queueCommand(state,{type,castleId:c.id,officerId:b.dataset.assign,factionId:state.playerFactionId},R);dialog.close();render();}catch(err){notify(err.message);}});}
function confirmMonth(){if(state.ending){modal('<h2>'+ (state.ending.type==='victory'?'天下統一':'領城を失いました')+'</h2><p>月末報告と軍事の合戦記録を確認できます。記録・設定から表題へ戻り、別の旗で始められます。</p>');return;}const qs=[...state.commands,...state.diplomacyCommands,...state.militaryCommands];modal(`<h2>${state.month}月の評定を終える</h2><p>予約した命令と他家の内政を実行し、収支を処理します。</p><div class="notice">${qs.length?qs.map(q=>e(state.castles.find(c=>c.id===q.castleId).name)+'：'+((q.type==='scheme'?YabouIntrigue.labels[q.kind]:E.labels[q.type])||(YabouDiplomacy.labels[q.type]||({march:'進軍'}[q.type])))).join('<br>'):'今月の予約命令はありません。待機して次月へ進めます。'}</div>${state.events.pending?'<p class="notice">「'+e(YabouEvents.byId[state.events.pending.id].title)+'」が未選択です。次月に進むと見送りになります。</p>':''}<p class="muted">未命令の自城：${state.castles.filter(c=>c.ownerFactionId===state.playerFactionId&&!qs.some(q=>q.castleId===c.id)).map(c=>e(c.name)).join('・')||'なし'}<br>進行後は月末オートセーブを作成します。</p><button class="primary" id="commitMonth">確定して次月へ</button>`);$('#commitMonth').onclick=()=>{try{beginInteractiveMonth();}catch(err){notify('月次処理を中止しました：'+err.message);}};}
function showReport(){const report=state.reports.at(-1);if(!report){modal('<h2>月末報告</h2><p>まだ月末を迎えていません。命令を予約して「次月へ」で進めてください。</p><button id="worldNews">天下動静を読む</button>');$('#worldNews').onclick=worldNewsDialog;return;}const entries=report.entries.filter(x=>x.factionId===state.playerFactionId),annual=report.month===12;modal(`<span class="eyebrow">${annual?'YEAR IN REVIEW':'MONTHLY REPORT'}</span><h2>第${report.year}年 ${report.month}月の報告</h2><button id="worldNews">天下動静を読む</button>${annual&&!state.ending?'<div class="notice">初年度の12か月を完了しました。翌年も内政を続けられます。</div>':''}<div class="dialogScroll"><table><thead><tr><th>城</th><th>税収</th><th>糧消費</th><th>収穫</th></tr></thead><tbody>${entries.map(x=>`<tr><td>${e(M.castles.find(c=>c.id===x.castleId).name)}</td><td>+${x.income}</td><td>−${x.use}${x.shortage?'（不足'+x.shortage+'）':''}</td><td>${x.harvest?'+'+x.harvest:'—'}</td></tr>`).join('')}</tbody></table></div><h3>施策</h3><p>${report.commands.filter(q=>q.factionId===state.playerFactionId).map(q=>e(M.castles.find(c=>c.id===q.castleId).name)+'：'+E.labels[q.type]).join('<br>')||'今月は待機しました。'}</p><h3>人材・忠誠の報告</h3><p>${(report.personnel||[]).filter(x=>x.factionId===state.playerFactionId).map(x=>e(x.text)).join('<br>')||'今月の人材の変化なし'}</p><h3>武将の言葉</h3><div id="monthDialogue">${state.personnel.dialogue.history.filter(h=>h.turn===report.turn&&h.factionId===state.playerFactionId).map(h=>'<p><strong>'+e(state.officers.find(o=>o.id===h.officerId).name)+'</strong>「'+e(h.text)+'」</p>').join('')||'<p>今月の返答なし</p>'}</div><h3>諸国の旗揚げ</h3><p>${state.personnel.independence.foundings.filter(b=>b.turn===report.turn).map(b=>e(faction(b.factionId).name)+'が'+e(M.castles.find(c=>c.id===b.castleId).name)+'で独立。旧主：'+e(faction(b.parentFactionId).name)).join('<br>')||'新たな旗揚げなし'}</p><h3>外交の報告</h3><p>${(report.diplomacy||[]).filter(q=>q.factionId===state.playerFactionId||q.targetFactionId===state.playerFactionId).map(q=>e(faction(q.factionId).name)+' → '+e(faction(q.targetFactionId).name)+'：'+e(q.result)).join('<br>')||'今月は交渉なし'}</p>${state.ending?'<p class="notice">'+(state.ending.type==='victory'?'全12城を支配し、軍事統一を達成しました。':'全領城を失い、今回の戦いは終了しました。')+'</p>':''}<h3>軍事の報告</h3><p>${(report.battles||[]).map(h=>e(M.castles.find(c=>c.id===h.castleId).name)+'：'+e(faction(h.winner==='attack'?h.attacker:h.defender).name)+' 勝利 / '+e(h.reason)).join('<br>')||'今月の合戦なし'}<br>${(report.military||[]).map(x=>e(M.castles.find(c=>c.id===x.castleId).name)+'：'+e(x.result)).join('<br>')}</p>${state.offers.length?'<p class="notice">返答待ちの外交提案があります。外交画面で確認してください。</p>':''}${annual?annualHTML(report.year):''}<h3>出来事と便り</h3><p>${(report.events||[]).map(x=>e(x.text)).join('<br>')||'今月の新しい便りなし'}</p><button id="readEvents">${state.events.pending||state.personnel.drama.pending?'届いた出来事を読む':'出来事の記録'}</button><button id="aiReport">他家の判断を見る</button>`);$('#worldNews').onclick=worldNewsDialog;$('#readEvents').onclick=showEvents;$('#aiReport').onclick=()=>{modal(`<h2>第${report.year}年 ${report.month}月 他家の判断</h2><p class="muted">人事・内政・外交・進軍の採択理由です。探索先の未発見武将は表示しません。</p><h3>確認された登用</h3><p id="enemyHires">${(report.personnel||[]).filter(x=>x.factionId!==state.playerFactionId&&x.text.includes('を登用した。')).map(x=>e(faction(x.factionId).name)+'：'+e(x.text)).join('<br>')||'今月の登用報告なし'}</p><h3>採択した行動と理由</h3>${state.aiLog.filter(x=>x.turn===report.turn).map(x=>`<div class="notice"><b>${e(faction(x.factionId).name)} / ${e(M.castles.find(c=>c.id===x.castleId).name)}</b><br>${E.labels[x.chosen]||(x.chosen==='march'?'進軍':'外交')}：${e(x.reason)}<br><small>候補 ${x.candidates.map(c=>E.labels[c.type]+' '+c.score.toFixed(1)).join(' / ')}</small></div>`).join('')}`);};}
function worldNewsDialog(){
 const N=YabouNews,date=t=>'第'+(Math.floor((t-1)/12)+1)+'年 '+((t-1)%12+1)+'月';let page=0;
 modal(`<section class="newsScreen"><header class="newsHeading"><div><span class="eyebrow">CHRONICLE OF THE REALM</span><h2>天下動静</h2></div><span class="newsSeal">諸国の便り</span></header><div class="newsControls"><label>期間<select id="newsMonths"><option value="3">直近3か月</option><option value="12" selected>直近12か月</option><option value="120">直近120か月</option></select></label><label>情報<select id="newsCertainty"><option value="all">すべて</option><option value="confirmed">確報のみ</option><option value="rumor">未確認の噂のみ</option></select></label><label>分野<select id="newsKind"><option value="all">すべての分野</option>${Object.entries(N.labels).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label>勢力<select id="newsFaction"><option value="all">全勢力・勢力不明</option>${state.factions.map(f=>`<option value="${f.id}">${e(f.name)}${W.aliveFaction(state,f.id)?'':'（滅亡）'}</option>`).join('')}</select></label></div><div id="newsCount" role="status"></div><div id="newsList"></div><nav class="newsPages" aria-label="天下動静のページ"><button id="newsPrev">前の20件</button><span id="newsPage"></span><button id="newsNext">次の20件</button></nav><details class="newsAbout"><summary>便りの見方・掲載範囲</summary><p class="newsIntro">合戦・登用・外交・内紛・独立を、記録に残る範囲でお伝えします。<b>確報</b>と<b>未確認の噂</b>を区別し、探索中の人材や他家の工作準備は掲載しません。</p><p class="newsNote">勢力不明の噂は「全勢力」で表示。保存済み記録の最新600件までを掲載し、過去に残っていない出来事は補いません。</p></details><details class="newsTreaties"><summary>現在の同盟・停戦</summary><p>これは現在の条約一覧です。成立月が記録されていない条約の過去の経緯は推測しません。</p>${N.treaties(state).map(t=>`<p>${e(faction(t.a).name)}・${e(faction(t.b).name)}：${t.kind}／残り${t.remaining}か月</p>`).join('')||'<p>現在、有効な同盟・停戦はありません。</p>'}</details></section>`);
 const draw=()=>{const v=N.view(state,{months:$('#newsMonths').value,certainty:$('#newsCertainty').value,kind:$('#newsKind').value,factionId:$('#newsFaction').value,page});page=v.page;$('#newsCount').textContent=v.total+'件：確報 '+v.confirmed+'／未確認の噂 '+v.rumors;$('#newsList').innerHTML=v.rows.map(x=>`<article class="newsItem ${x.certainty}" data-news-id="${e(x.id)}" data-certainty="${x.certainty}"><div class="newsMeta"><span class="newsBadge">${x.certainty==='confirmed'?'確報':'未確認の噂'}</span><span>${date(x.turn)}／${N.labels[x.kind]}</span></div><h3>${e(x.title)}</h3><p>${e(x.text)}</p><footer><small>出典：${e(x.source)}</small>${x.castleId?`<button data-news-castle="${x.castleId}">城を地図で見る</button>`:''}</footer></article>`).join('')||'<p class="notice">この条件に合う便りはありません。期間や勢力の条件を変えて確認できます。</p>';$('#newsPage').textContent=(page+1)+' / '+v.pages;$('#newsPrev').disabled=page===0;$('#newsNext').disabled=page===v.pages-1;document.querySelectorAll('[data-news-castle]').forEach(b=>b.onclick=()=>{dialog.close();selectCastle(b.dataset.newsCastle);});};
 for(const id of ['newsMonths','newsCertainty','newsKind','newsFaction'])$('#'+id).onchange=()=>{page=0;draw();};$('#newsPrev').onclick=()=>{page--;draw();$('#dialogContent').scrollTop=0;};$('#newsNext').onclick=()=>{page++;draw();$('#dialogContent').scrollTop=0;};draw();
}

function annualHTML(year){const rs=state.annualReports.find(x=>x.year===year).reports;const entries=rs.flatMap(x=>x.entries).filter(x=>x.factionId===state.playerFactionId);return `<h3>年次集計</h3><p>税収合計 ${num(entries.reduce((a,x)=>a+x.income,0))} / 収穫合計 ${num(entries.reduce((a,x)=>a+x.harvest,0))}<br>兵糧消費 ${num(entries.reduce((a,x)=>a+x.use,0))} / 不足 ${num(entries.reduce((a,x)=>a+x.shortage,0))}</p>`;}
function saveMenu(){modal(`<h2>記録・設定</h2><p>現在：第${state.year}年${state.month}月 / ${e(faction(state.playerFactionId).name)}<br><span id="currentScenario">${e(YabouScenarios.get(state.scenarioId).name)}</span></p><div class="sectionButtons"><button id="export">JSON書出し</button><button id="import">JSON読込</button><button id="restore">月末から再開</button><button id="beforeBattle">出陣前から再開</button><button id="backup">前回の月末から復旧</button></div><h3>手動記録</h3>${[1,2,3].map(i=>`<div>記録 ${i} <button data-save="${i}">保存</button><button data-load="${i}">読込</button></div>`).join('')}<button id="readPrologue">プロローグを読み返す</button><h3>表示</h3><button id="fontSize">文字サイズ切替</button><button id="toTitle">表題へ戻る</button><p class="muted"><small>予約命令も手動記録できます。合戦開始前を自動記録し、中断時はそこから再挑戦できます。<br>ブラウザの保存領域が使えない場合はJSONで保管してください。</small></p>`);
 $('#readPrologue').onclick=()=>prologueDialog(true);$('#export').onclick=()=>{const blob=new Blob([E.serializeSave(state,M,R)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aobee-yabou-${state.year}-${state.month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onclick=()=>$('#importFile').click();$('#restore').onclick=()=>confirmLoad(key);$('#beforeBattle').onclick=()=>confirmLoad(key+'-before-battle');$('#backup').onclick=()=>confirmLoad(key+'.backup');document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{modal(`<h2>記録${b.dataset.save}を保存</h2><p>この記録枠を現在の状態で置き換えます。</p><button class="primary" id="confirmSave">保存する</button>`);$('#confirmSave').onclick=()=>{if(save(key+'-'+b.dataset.save)){dialog.close();notify('手動記録を保存しました');}};});document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>confirmLoad(key+'-'+b.dataset.load));$('#fontSize').onclick=()=>{const n=Number(document.documentElement.dataset.font||16);const next=n===16?18:n===18?20:16;document.documentElement.dataset.font=next;document.documentElement.style.fontSize=next+'px';};$('#toTitle').onclick=()=>{modal('<h2>表題へ戻る</h2><p>未保存の変更は失われます。必要なら先に手動記録してください。</p><button id="confirmTitle">表題へ戻る</button>');$('#confirmTitle').onclick=()=>{dialog.close();welcome();};};}
function confirmLoad(slot){modal('<h2>記録から再開</h2><p>現在の未保存の変更を破棄して、記録を読み込みます。</p><button class="primary" id="confirmLoad">読み込む</button>');$('#confirmLoad').onclick=()=>load(slot);}
$('#importFile').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('ファイルが大きすぎます');const next=E.loadSave(await file.text(),M,R);modal('<h2>JSONから再開</h2><p>検証に成功しました。現在の未保存の変更を破棄して読み込みます。</p><button class="primary" id="acceptImport">この記録で再開</button>');$('#acceptImport').onclick=()=>{state=next;selected=faction(state.playerFactionId).capitalCastleId||state.castles[0].id;dialog.close();render();notify('JSONを読み込みました。既存の保存枠は変更していません');};}catch(err){notify('読込できません：'+err.message);}finally{ev.target.value='';}};
function setupMap(){const svg=$('#map'),points=new Map();let origin=null,moved=false,pinch=null;const update=()=>{const w=$('#world');if(w)w.setAttribute('transform',`translate(${camera.x} ${camera.y}) scale(${zoom})`);};function setZoom(next){next=Math.min(3,Math.max(1,next));const ratio=next/zoom;const centerX=svg.viewBox.baseVal.width/2,centerY=svg.viewBox.baseVal.height/2;camera.x=centerX-(centerX-camera.x)*ratio;camera.y=centerY-(centerY-camera.y)*ratio;zoom=next;update();}$('#zoomIn').onclick=()=>setZoom(zoom*1.3);$('#zoomOut').onclick=()=>setZoom(zoom/1.3);$('#resetMap').onclick=()=>{zoom=1;camera={x:0,y:0};update();};svg.addEventListener('click',ev=>{if(moved){ev.stopImmediatePropagation();ev.preventDefault();}},true);
 svg.onpointerdown=ev=>{points.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(points.size===1){origin={x:ev.clientX,y:ev.clientY,cx:camera.x,cy:camera.y,castle:ev.target.closest("[data-castle]")?.dataset.castle};moved=false;pinch=null;}else if(points.size===2){const [a,b]=[...points.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom};}svg.setPointerCapture(ev.pointerId);};
 svg.onpointermove=ev=>{if(!points.has(ev.pointerId))return;points.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(points.size===2&&pinch){const[a,b]=[...points.values()];setZoom(pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance));moved=true;}else if(points.size===1&&origin){const dx=ev.clientX-origin.x,dy=ev.clientY-origin.y;if(Math.hypot(dx,dy)>8){moved=true;const rect=svg.getBoundingClientRect(),v=svg.viewBox.baseVal,scale=1/Math.min(rect.width/v.width,rect.height/v.height);camera.x=Math.max(-2500,Math.min(1000,origin.cx+dx*scale));camera.y=Math.max(-2500,Math.min(1000,origin.cy+dy*scale));update();}}};
 const release=ev=>{const tapped=!moved&&origin?.castle&&ev.type!=="pointercancel"?origin.castle:null;points.delete(ev.pointerId);if(!points.size){origin=null;pinch=null;}else{const p=[...points.values()][0];origin={x:p.x,y:p.y,cx:camera.x,cy:camera.y};pinch=null;}if(tapped)selectCastle(tapped);};svg.onpointerup=release;svg.onpointercancel=release;
 svg.addEventListener('wheel',ev=>{ev.preventDefault();setZoom(zoom*(ev.deltaY<0?1.1:1/1.1));},{passive:false});
}
window.addEventListener("resize",()=>{if(document.querySelector("#map")){zoom=1;camera={x:0,y:0};drawMap();}});
function openDiplomacy(){
 const D=YabouDiplomacy,own=state.playerFactionId;
 modal(`<div class="diplomacyScreen"><span class="eyebrow">DIPLOMACY</span><h2>諸家との交渉</h2><button id="diplomaticHistory">会話の記録</button><p class="muted">親善・同盟・停戦・交易。停戦は6か月、同盟は12か月（各家2勢力まで）。</p>${state.offers.filter(o=>o.expiresTurn>=state.turn).map(o=>`<div class="notice"><b>${e(faction(o.from).name)}から${o.type==='truce'?'6か月の停戦':'同盟'}の提案</b><br><small>返答期限：あと${o.expiresTurn-state.turn+1}ターン</small><br><button data-offer-talk="${e(o.id)}">武将に相談</button><button class="primary" data-accept="${e(o.id)}">受諾</button><button data-reject="${e(o.id)}">辞退</button></div>`).join('')}<div class="diplomacyGrid">${state.factions.filter(f=>f.id!==own&&W.aliveFaction(state,f.id)).map(f=>{const d=state.diplomacy[D.pair(own,f.id)],active=D.active(state,own,f.id);return `<section class="diplomacyCard" style="--color:${color(f.id)}"><strong>${e(f.name)}</strong><p>関係 <b>${d.relation>0?'+':''}${d.relation}</b> / ${active?'同盟中・残り'+(d.allianceUntil-state.turn)+'か月':D.truce(state,own,f.id)?'停戦中・残り'+(d.truceUntil-state.turn)+'か月':W.atWar(state,own,f.id)?'交戦中':'未同盟'}</p><button data-goodwill="${f.id}">贈物（金50）</button><button data-alliance="${f.id}">同盟交渉</button><button data-truce="${f.id}">停戦交渉</button><button data-trade="${f.id}">交易（金100→糧150）</button><button data-aid="${f.id}">援軍要請</button><button data-surrender="${f.id}">降伏勧告</button></section>`;}).join('')}</div><h3>今月の外交予約</h3>${state.diplomacyCommands.length?state.diplomacyCommands.map((q,i)=>`<div class="queue">${e(faction(q.targetFactionId).name)}：${D.labels[q.type]} / ${e(state.officers.find(o=>o.id===q.officerId).name)}<button data-cancel-diplomacy="${i}">取消</button></div>`).join(''):'<p class="muted">予約なし</p>'}<p class="muted"><small>交易は関係20以上。成立時だけ金100を相手の本城へ支払い、そこから兵糧150を受け取ります。停戦中は双方とも攻撃不可。援軍は同盟国から補充兵300・糧100を受領（成立時に金100）。降伏勧告は最後の一城を持つ隣接交戦国へ、3城以上・兵力3倍以上の優勢時に交渉できます。</small></p></div>`);
 $('#diplomaticHistory').onclick=dialogueHistoryDialog;document.querySelectorAll('[data-goodwill],[data-alliance],[data-truce],[data-trade],[data-aid],[data-surrender]').forEach(b=>b.onclick=()=>{const type=Object.keys(D.labels).find(t=>b.dataset[t]);diplomacyAssign(type,b.dataset[type]);});
 document.querySelectorAll('[data-cancel-diplomacy]').forEach(b=>b.onclick=()=>{state={...state,diplomacyCommands:state.diplomacyCommands.filter((_,i)=>i!==Number(b.dataset.cancelDiplomacy))};render();openDiplomacy();});
 document.querySelectorAll('[data-offer-talk]').forEach(b=>b.onclick=()=>offerTalkDialog(b.dataset.offerTalk));
 document.querySelectorAll('[data-accept],[data-reject]').forEach(b=>b.onclick=()=>{try{state=D.respond(state,b.dataset.accept||b.dataset.reject,!!b.dataset.accept);render();openDiplomacy();notify(b.dataset.accept?'条約を締結しました。手動記録または次の月末に保存されます':'提案を辞退しました');}catch(err){notify(err.message);}});
}
function offerTalkDialog(id){const D=YabouDiplomacy,view=YabouDialogue.offerPreview(state,id);if(!view){notify('相談できる武将または有効な提案がありません');return;}const o=state.officers.find(o=>o.id===view.officerId);modal(`<section class="diplomaticTalkScreen"><span class="eyebrow">届いた提案の評定</span><h2>${e(faction(view.offer.from).name)}からの${view.kind==='truce'?'停戦':'同盟'}提案</h2><p class="talkSpeaker">相談役：${e(o.name)}</p><blockquote class="talkQuote">${e(view.text)}</blockquote><p class="talkTerms">受諾時：${view.kind==='truce'?'6か月の停戦・双方とも攻撃不可':'12か月の同盟・各家2勢力まで'}。返答期限まであと${view.offer.expiresTurn-state.turn+1}ターン。</p><p class="muted">相談は無料。受諾・辞退は即時に確定し、手動記録または次の月末に保存されます。</p><div class="talkActions"><button class="primary" id="acceptOfferTalk">受諾する</button><button id="declineOfferTalk">辞退する</button><button id="backOfferTalk">返答せず戻る</button></div></section>`);$('#backOfferTalk').onclick=openDiplomacy;const respond=accept=>{try{state=D.respond(state,id,accept);render();openDiplomacy();notify(accept?'条約を締結しました':'提案を辞退しました');}catch(err){notify(err.message);}};$('#acceptOfferTalk').onclick=()=>respond(true);$('#declineOfferTalk').onclick=()=>respond(false);}
function diplomaticTalkDialog(q){
 const D=YabouDiplomacy,T=YabouDialogue,o=state.officers.find(o=>o.id===q.officerId),line=T.diplomaticPreview(state,q);if(!o||!line)return;const reason=D.can(state,q,R),terms={goodwill:'金50を使い、関係+10。同盟の締結は別の交渉です。',alliance:'成立時は12か月の同盟。各家2勢力までです。',truce:'成立時は6か月の停戦。期間中は双方とも攻撃できません。',trade:'成立時だけ金100を払い、相手の本城から兵糧150を受け取ります。',aid:'成立時だけ金100を払い、補充兵300・兵糧100を受け取ります。',surrender:'成立時は相手の最後の一城と現役武将を編入。元大名も家臣になります。'};
 modal(`<section class="diplomaticTalkScreen"><div class="talkHeading"><span class="eyebrow">使者との評定</span><h2>${e(faction(q.targetFactionId).name)}へ${D.labels[q.type]}</h2></div><p class="talkSpeaker">使者：${e(o.name)}／出発：${e(M.castles.find(c=>c.id===q.castleId).name)}</p><blockquote class="talkQuote">${e(line.text)}</blockquote><p class="talkTerms">${terms[q.type]}${q.type!=='goodwill'&&!reason?' 現在の成功率の目安 '+D.chance(state,q).toFixed(1)+'%。':''}</p><p class="muted">閲覧は費用・任務を使いません。結果は月末に確定し、成立・不成立・中止を報告します。</p><div class="talkActions"><button id="queueDiplomaticTalk" class="primary" ${reason?'disabled':''}>この使者で交渉を予約</button><button id="backDiplomaticTalk">使者の選択に戻る</button></div>${reason?'<p class="notice">'+e(reason)+'</p>':''}</section>`);
 $('#backDiplomaticTalk').onclick=()=>diplomacyAssign(q.type,q.targetFactionId);$('#queueDiplomaticTalk').onclick=()=>{try{state=D.queue(state,q,R);render();openDiplomacy();notify('外交を予約しました。返答は月末に届きます');}catch(err){notify(err.message);}};
}

function diplomacyAssign(type,target){const D=YabouDiplomacy;modal(`<div class="diplomacyScreen"><h2>${e(faction(target).name)}へ${D.labels[type]}</h2><p>${({goodwill:'出発城の金50を使い、関係+10。',alliance:'関係30以上が必要。成立時は12か月の同盟。',truce:'交戦中の相手に6か月の停戦を交渉。成立後は双方とも攻撃できません。',trade:'関係20以上。成立時に出発城の金100と相手本城の兵糧150を交換。不成立時は交換なし。',aid:'同盟国へ補充兵を要請。成立時に金100を支払い、相手本城の兵300・兵糧100を出発城へ移します。相手の守備兵600と6か月分の兵糧を残せる場合のみ。共同出陣ではなく、自城への補充です。',surrender:'隣接する交戦国が最後の一城、自家が3城以上・兵力3倍以上で勧告できます。成立すると、その城と資源・兵を編入し、現役武将は忠誠60の家臣になります（元大名も家臣）。他家に捕らわれた武将は自動解放しません。拒否されれば所属は変わりません。'})[type]} 交渉が不成立でも使者の任務は消費します。</p><p class="muted">城の2命令枠と武将の1任務枠を内政と共有します。</p>${state.officers.filter(o=>o.factionId===state.playerFactionId).map(o=>{const q={type,targetFactionId:target,officerId:o.id,castleId:o.locationCastleId,factionId:state.playerFactionId},reason=D.can(state,q,R);return `<div><button data-diplomat="${o.id}" ${reason?'disabled':''}>${e(o.name)}で予約</button><button data-diplomatic-talk="${o.id}" ${reason?'disabled':''}>使者の話を聞く</button><small class="muted">${reason?e(reason):type!=='goodwill'?'成功率 '+D.chance(state,q).toFixed(1)+'%':'知略 '+o.stats.intellect}</small></div>`;}).join('')}<button id="backDiplomacy">外交一覧へ</button></div>`);
 $('#backDiplomacy').onclick=openDiplomacy;document.querySelectorAll('[data-diplomatic-talk]').forEach(b=>b.onclick=()=>{const o=state.officers.find(o=>o.id===b.dataset.diplomaticTalk);diplomaticTalkDialog({type,targetFactionId:target,officerId:o.id,castleId:o.locationCastleId,factionId:state.playerFactionId});});document.querySelectorAll('[data-diplomat]').forEach(b=>b.onclick=()=>{try{const o=state.officers.find(o=>o.id===b.dataset.diplomat);state=D.queue(state,{type,targetFactionId:target,officerId:o.id,castleId:o.locationCastleId,factionId:state.playerFactionId},R);render();openDiplomacy();}catch(err){notify(err.message);}});
}

let monthTransaction=null,fieldBattle=null,battleOrders={},selectedUnit=null,battleAction='move';
const W=YabouMilitary,B=YabouBattle;
function councilDialog(from=selected,to=null,advisor=null){
 const own=state.castles.filter(c=>c.ownerFactionId===state.playerFactionId),c=own.find(c=>c.id===from)||own[0];if(!c){openMilitary();return;}const targets=M.roads.flatMap(r=>r.fromCastleId===c.id?[r.toCastleId]:r.toCastleId===c.id?[r.fromCastleId]:[]).map(id=>state.castles.find(c=>c.id===id)),t=targets.find(t=>t.id===to)||targets[0],os=state.officers.filter(o=>o.status==='active'&&o.factionId===state.playerFactionId&&o.locationCastleId===c.id),o=os.find(o=>o.id===advisor)||os[0];
 modal(`<section class="councilScreen"><header class="councilHeading"><h2>家臣との軍議</h2><button id="councilHistory">会話記録</button></header><div class="councilControls"><label>出発城<select id="councilFrom">${own.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><label>隣接する城<select id="councilTo">${targets.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${e(x.name)}／${e(faction(x.ownerFactionId).name)}</option>`).join('')}</select></label><label>助言する武将<select id="councilOfficer">${os.map(x=>`<option value="${x.id}" ${x.id===o?.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label></div><div id="councilBody"></div><div class="councilActions"><button id="councilMarch" class="primary">${t.ownerFactionId===state.playerFactionId?'移送の編成へ':'出陣の編成へ'}</button><button id="councilFortify">この城の城防を整える</button><button id="councilDiplomacy">外交で備える</button><button id="councilBack">軍事一覧へ</button></div><details class="councilHelp"><summary>助言と数値の見方</summary><p>閲覧は無料で、武将の任務・乱数・会話記録を消費しません。未予約の兵と兵糧、空いている武将・命令枠を表示します。編成の目安は兵数から計算し、携行兵糧は編成画面で別途確認します。</p><p>相手の兵数は現在の城兵です。将の能力・部隊数・地形・士気・天候・月末までの変化で勝敗は変わります。敵の予約命令や未発見情報を参照した予測ではありません。出陣の可否・費用・宣戦は既存の編成画面で確認します。</p></details></section>`);
 const info=o?YabouDialogue.councilPreview(state,{castleId:c.id,targetCastleId:t.id,officerId:o.id}):null;
 $('#councilBody').innerHTML=info?`<div class="councilQuote" data-advice="${info.key}"><strong>${e(o.name)}</strong><blockquote class="talkQuote">${e(info.text)}</blockquote></div><div class="councilStats">${[['未予約の兵',info.availableTroops],['未予約の兵糧',info.availableFood],['任務が空く武将',info.freeOfficers],['城の残り命令枠',info.slots],['追加編成の目安',info.deployable],['相手の城兵',info.targetTroops]].map(([label,value])=>`<div><span>${label}</span><b>${num(value)}</b></div>`).join('')}</div>${info.blockedReason?'<p class="notice">'+e(info.blockedReason)+'</p>':''}`:'<p class="notice">この城で助言する現役武将はいません。配置と城の状況を確認してください。</p>';
 $('#councilFrom').onchange=()=>councilDialog($('#councilFrom').value);$('#councilTo').onchange=()=>councilDialog(c.id,$('#councilTo').value,$('#councilOfficer').value);$('#councilOfficer').onchange=()=>councilDialog(c.id,t.id,$('#councilOfficer').value);$('#councilHistory').onclick=dialogueHistoryDialog;$('#councilMarch').disabled=!info||!!info.blockedReason;$('#councilMarch').onclick=()=>marchForm(c.id,t.id);$('#councilFortify').disabled=!!state.ending;$('#councilFortify').onclick=()=>{selected=c.id;tab='内政';render();commandDialog('fortify',c);};$('#councilDiplomacy').disabled=!!state.ending||t.ownerFactionId===state.playerFactionId;$('#councilDiplomacy').onclick=()=>diplomacyAssign(W.atWar(state,state.playerFactionId,t.ownerFactionId)?'truce':'goodwill',t.ownerFactionId);$('#councilBack').onclick=()=>{selected=c.id;openMilitary();};
}

function openMilitary(){
 const own=state.castles.filter(c=>c.ownerFactionId===state.playerFactionId),source=own.find(c=>c.id===selected)||own[0];
 if(!source){modal('<h2>領城を失いました</h2><p>戦歴と月末報告を確認できます。表題から新しい旗で再挑戦してください。</p>');return;}
 modal(`<span class="eyebrow">MARCH & BATTLE</span><h2>軍議を開く</h2><button id="councilOpen">家臣の助言を聞く</button><button id="militaryTalkHistory">会話の記録</button><p>街道で隣接した城へ進軍。自城なら兵と武将を移送します。</p><label>出発城 <select id="marchFrom">${own.map(c=>`<option value="${c.id}" ${source.id===c.id?'selected':''}>${e(c.name)} / 兵${c.troops}</option>`).join('')}</select></label><div id="marchTargets"></div><h3>出陣予約</h3>${state.militaryCommands.map((q,i)=>`<div class="queue">${e(M.castles.find(c=>c.id===q.castleId).name)} → ${e(M.castles.find(c=>c.id===q.targetCastleId).name)} / ${q.units.reduce((a,u)=>a+u.troops,0)}兵<button data-cancel-march="${i}">取消</button></div>`).join('')||'<p class="muted">予約なし</p>'}<h3>自家の捕虜</h3>${state.officers.filter(o=>o.status==='prisoner'&&o.captorFactionId===state.playerFactionId).map(o=>`<div class="queue">${e(o.name)}<button data-release="${o.id}">解放</button></div>`).join('')||'<p class="muted">捕虜なし</p>'}<button id="history">合戦記録</button><p class="muted"><small>各城月1回の出陣。最大3部隊、1部隊100〜3000兵。出発城には最低100兵を残します。<br>停戦は外交画面から交渉できます。捕虜登用・従属・長期包囲は今後の段階です。</small></p>`);
 const targets=()=>{const c=state.castles.find(c=>c.id===$('#marchFrom').value);const ids=M.roads.flatMap(r=>r.fromCastleId===c.id?[r.toCastleId]:r.toCastleId===c.id?[r.fromCastleId]:[]);$('#marchTargets').innerHTML='<h3>隣接城</h3>'+ids.map(id=>{const t=state.castles.find(x=>x.id===id),ally=t.ownerFactionId!==c.ownerFactionId&&YabouDiplomacy.active(state,c.ownerFactionId,t.ownerFactionId);return `<div class="marchTarget"><div><b>${e(t.name)}</b><br><small>${e(faction(t.ownerFactionId).name)} / 兵${t.troops} / 城防${t.defense}${ally?' / 同盟中':''}</small></div><button data-march-to="${id}" ${ally||state.ending?'disabled':''}>${t.ownerFactionId===c.ownerFactionId?'移送を編成':'出陣を編成'}</button></div>`;}).join('');document.querySelectorAll('[data-march-to]').forEach(b=>b.onclick=()=>marchForm(c.id,b.dataset.marchTo));};$('#marchFrom').onchange=targets;targets();$('#councilOpen').onclick=()=>councilDialog($('#marchFrom').value);$('#militaryTalkHistory').onclick=dialogueHistoryDialog;
 document.querySelectorAll('[data-cancel-march]').forEach(b=>b.onclick=()=>{state={...state,militaryCommands:state.militaryCommands.filter((_,i)=>i!==Number(b.dataset.cancelMarch))};render();openMilitary();});
 document.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>{modal(`<h2>捕虜を解放する</h2><p>主家が存続していれば帰還し、滅亡していれば浪人になります。</p><button id="releaseConfirm">解放する</button>`);$('#releaseConfirm').onclick=()=>{state=W.release(state,b.dataset.release);render();openMilitary();};});
 $('#history').onclick=()=>modal(`<h2>合戦記録</h2>${state.battleHistory.slice().reverse().slice(0,12).map(h=>`<details><summary>${e(M.castles.find(c=>c.id===h.castleId).name)} / ${h.winner==='attack'?'攻城軍':'守備軍'}勝利</summary><p>${e(h.reason)} / ${h.rounds}R<br>攻城軍損耗 ${h.attackLosses} / 守備軍損耗 ${h.defendLosses}${h.surrendered?' / 降伏兵 '+h.surrendered:''}</p><div class="battleLog">${h.log.map(e).join('<br>')}</div></details>`).join('')||'<p>まだ合戦はありません。</p>'}`);
}
function marchForm(from,to){const c=state.castles.find(c=>c.id===from),t=state.castles.find(c=>c.id===to),officers=state.officers.filter(o=>o.status==='active'&&o.locationCastleId===from&&o.factionId===state.playerFactionId);
 modal(`<h2>${e(c.name)} → ${e(t.name)}</h2><p>守備兵 ${t.troops} / 城防 ${t.defense} / ${e(faction(t.ownerFactionId).name)}</p><div class="notice">兵糧を多く積むほど遠征の備蓄が減ります。100兵あたり12ラウンドで兵糧12。戦闘は最大3部隊対3部隊です。</div><div class="marchRoster">${officers.map((o,i)=>`<div><label><input type="checkbox" data-march-officer="${o.id}" ${i===0?'checked':''}> ${e(o.name)} <small>統率${o.stats.leadership}</small></label><label>兵種 <select data-unit-type="${o.id}">${Object.entries(B.RULES.types).map(([id,v])=>`<option value="${id}">${v.name}</option>`).join('')}</select></label><label>兵数 <input type="number" data-unit-troops="${o.id}" value="${i===0?Math.min(800,Math.max(100,c.troops-100)):100}" min="100" max="3000" step="100"></label></div>`).join('')}</div><label>携行兵糧 <input type="number" id="marchFood" min="12" max="${c.food}" value="${Math.min(c.food,120)}"></label><p id="marchEstimate" class="notice"></p><p id="marchError" role="status"></p><button class="primary" id="marchConfirm">編成を確認</button><button id="backMilitary">軍議へ戻る</button>`);
 const query=()=>({type:'march',factionId:state.playerFactionId,castleId:from,targetCastleId:to,units:[...document.querySelectorAll('[data-march-officer]:checked')].map(b=>({officerId:b.dataset.marchOfficer,type:document.querySelector(`[data-unit-type="${b.dataset.marchOfficer}"]`).value,troops:Number(document.querySelector(`[data-unit-troops="${b.dataset.marchOfficer}"]`).value)})),food:Number($('#marchFood').value),declareWar:true});
 const estimate=()=>{const q=query(),sum=q.units.reduce((a,u)=>a+u.troops,0),required=q.units.reduce((a,u)=>a+Math.ceil(u.troops/100)*12,0),error=W.can(state,q,M,R);$('#marchEstimate').textContent=`出陣 ${sum}兵 / 城に残す兵 ${c.troops-sum} / 必要兵糧 ${required}。${t.ownerFactionId===state.playerFactionId?'友軍への移送です。':'兵力比 '+(sum/Math.max(1,t.troops)).toFixed(2)+'倍。地形・士気・補給により勝敗は変わります。'}`;$('#marchError').textContent=error||'予約できます';$('#marchConfirm').disabled=!!error;};document.querySelectorAll('.marchRoster input,.marchRoster select,#marchFood').forEach(n=>n.oninput=estimate);estimate();$('#backMilitary').onclick=openMilitary;
 $('#marchConfirm').onclick=()=>{const q=query(),war=t.ownerFactionId!==state.playerFactionId&&!W.atWar(state,state.playerFactionId,t.ownerFactionId);modal(`<h2>${war?'宣戦と出陣を確認':t.ownerFactionId===state.playerFactionId?'移送を確認':'出陣を確認'}</h2><p>${e(c.name)}から${e(t.name)}へ ${q.units.reduce((a,u)=>a+u.troops,0)}兵・兵糧${q.food}を送ります。</p>${war?'<div class="notice">未交戦の相手です。月末の出陣時に宣戦し、関係が35低下します。</div>':''}<p>月末に実行。確定前は軍議から取消できます。</p><button class="primary" id="queueMarch">出陣を予約</button>`);$('#queueMarch').onclick=()=>{try{state=W.queue(state,q,M,R);dialog.close();render();notify('出陣を予約しました');}catch(err){notify(err.message);}};};
}
function beginInteractiveMonth(){
 try{save(key+'-before-battle');monthTransaction=E.beginMonth(state,M,R);continueCampaign();}catch(err){monthTransaction=null;fieldBattle=null;notify('月次処理を中止しました：'+err.message);}
}
function continueCampaign(){
 try{let b;while((b=E.nextBattle(monthTransaction))){if(b.attacker===state.playerFactionId||b.defender===state.playerFactionId){fieldBattle=b;battleOrders={};selectedUnit=b.units.find(u=>u.side===(b.attacker===state.playerFactionId?'attack':'defend'))?.id;showBattle();return;}W.settle(monthTransaction,B.auto(b));}
 const next=E.finishMonth(monthTransaction,M,R);state=next;monthTransaction=null;fieldBattle=null;$('#closeModal').hidden=false;save();render();showReport();
 }catch(err){monthTransaction=null;fieldBattle=null;$('#closeModal').hidden=false;modal('<h2>月次処理を中止しました</h2><p>開始前の状態を保持しました。'+e(err.message)+'</p>');notify('出陣前の記録から再開できます');}
}
function showBattle(){
 const b=fieldBattle,side=b.attacker===state.playerFactionId?'attack':'defend',own=b.units.filter(u=>u.side===side&&B.alive(u));if(!own.some(u=>u.id===selectedUnit))selectedUnit=own[0]?.id;const u=own.find(u=>u.id===selectedUnit),terrainNames={plain:'平',forest:'森',mountain:'山',river:'川',castle:'城'};
 const reachable=u?B.reachable(b,u):[];const tacticLabel=q=>({move:'移動 '+(q.x+1)+','+(q.y+1),attack:'攻撃',charge:'突撃',confuse:'攪乱',ambush:'伏兵',guard:'守備',retreat:'撤退'}[q.type]);const predictions=u?b.units.filter(v=>v.side!==side&&B.alive(v)&&!B.legal(b,u,{type:'attack',targetId:v.id})).map(v=>{const p=B.predict(b,u,v);return e(v.name)+'：'+p.min+'〜'+p.max;}).join('<br>'):'';modal(`<section class="battleScreen"><header class="battleHeader"><div><span class="eyebrow">TACTICAL BATTLE / 暫定戦闘式</span><h2>${e(M.castles.find(c=>c.id===monthTransaction.current.army.targetCastleId).name)}の合戦</h2></div><p>第${Math.min(12,b.round)} / 12 R　${b.weather}<br><small>自軍：${side==='attack'?'攻城軍':'守備軍'} / 兵糧 ${b.food[side]}</small></p></header>${b.result?`<div class="notice">${b.result.winner===side?'勝利':'敗北'}：${e(b.result.reason)}</div>`:''}<div class="battleLayout"><div class="battleBoard" role="group" aria-label="8×6戦術盤">${b.terrain.map((t,i)=>{const x=i%8,y=Math.floor(i/8),unit=b.units.find(v=>v.x===x&&v.y===y&&B.alive(v)),enemy=unit&&unit.side!==side,canMove=battleAction==='move'&&reachable.some(p=>p.x===x&&p.y===y);let prediction='';if(enemy&&u&&!B.legal(b,u,{type:'attack',targetId:unit.id})){const p=B.predict(b,u,unit);prediction=`予測損害 ${p.min}〜${p.max}`;}return `<button class="battleCell terrain-${t} ${unit?enemy?'enemyUnit':'ownUnit':''} ${unit?.id===selectedUnit?'selectedUnit':''} ${canMove?'reachable':''}" data-cell="${i}" aria-label="${x+1},${y+1} ${terrainNames[t]} ${unit?e(unit.name)+' '+unit.troops+'兵 '+prediction:''}"><small>${terrainNames[t]}</small>${unit?`<b>${unit.side==='attack'?'攻':'守'}${unit.id.slice(-1)*1+1}</b><span>${unit.troops}</span>`:''}</button>`;}).join('')}</div><aside class="battlePanel"><h3>自軍部隊を選択</h3>${own.map(v=>`<button class="unitPick ${v.id===selectedUnit?'primary':''}" data-pick="${v.id}">${e(v.name)} / ${B.RULES.types[v.type].name}<small>兵${v.troops}・士気${v.morale} / ${e(battleOrders[v.id]?tacticLabel(battleOrders[v.id]):'守備（未指定）')}</small></button>`).join('')}${!b.result&&u?`<label>命令 <select id="battleAction">${[['move','移動'],['attack','通常攻撃'],['charge','突撃'],['confuse','攪乱'],['ambush','伏兵'],['guard','守備'],['retreat','撤退']].map(([id,name])=>`<option value="${id}" ${battleAction===id?'selected':''}>${name}</option>`).join('')}</select></label><p class="muted"><small>移動は行き先、攻撃・攪乱は敵を選択。守備・伏兵・撤退は下のボタンで予約。</small></p><button id="setTactic">選択命令を予約</button>`:''}${predictions?'<p class="battlePrediction">現状の通常攻撃予測<br>'+predictions+'</p>':''}<div id="tacticHint" class="muted" role="status"></div></aside></div><footer class="battleFooter">${b.result?'<button id="battleDone" class="primary">戦後処理へ</button>':'<button id="roundCommit" class="primary">命令確定・1R進める</button><button id="autoRound">1Rおまかせ</button><button id="autoBattle">残りの合戦を委任</button>'}</footer><details class="battleDetails" open><summary>戦況ログ・ルール</summary><p class="muted"><small>同時予約・速度順。総大将離脱で敗北。12R以内に攻城できなければ守備側勝利。兵糧不足は士気−15・攻撃0.8倍。未指定の自軍は守備。</small></p><div class="battleLog">${b.log.slice(-12).map(e).join('<br>')||'部隊を選んで命令を予約してください。味方の旗と敵の旗は輪郭でも区別しています。'}</div></details></section>`);$('#closeModal').hidden=true;
 document.querySelectorAll('[data-pick]').forEach(n=>n.onclick=()=>{selectedUnit=n.dataset.pick;showBattle();});
 const stage=q=>{const error=B.legal(b,u,q);if(error){$('#tacticHint').textContent=error;return;}battleOrders[u.id]=q;showBattle();};
 document.querySelectorAll('[data-cell]').forEach(n=>n.onclick=()=>{if(b.result)return;const i=Number(n.dataset.cell),x=i%8,y=Math.floor(i/8),target=b.units.find(v=>v.x===x&&v.y===y&&B.alive(v));if(target?.side===side){selectedUnit=target.id;showBattle();return;}if(!u)return;if(['attack','charge','confuse'].includes(battleAction)&&target){stage({type:battleAction,targetId:target.id});return;}if(battleAction==='move')stage({type:'move',x,y});});
 if(b.result){$('#battleDone').onclick=()=>{W.settle(monthTransaction,fieldBattle);fieldBattle=null;continueCampaign();};return;}
 $('#battleAction').onchange=ev=>{battleAction=ev.target.value;showBattle();};$('#setTactic').onclick=()=>{if(['guard','retreat','ambush'].includes(battleAction))stage({type:battleAction});else $('#tacticHint').textContent='戦術盤の行き先または敵を選択してください。';};
 function round(auto){try{const orders={...B.aiOrders(b,side==='attack'?'defend':'attack')};for(const v of own)orders[v.id]=auto?B.aiOrders(b,side)[v.id]:battleOrders[v.id]||{type:'guard'};fieldBattle=B.advance(b,orders);battleOrders={};showBattle();}catch(err){notify(err.message);}}
 $('#roundCommit').onclick=()=>round(false);$('#autoRound').onclick=()=>round(true);$('#autoBattle').onclick=()=>{modal('<h2>合戦を委任する</h2><p>残りのラウンドを共通の合戦AIで解決します。兵糧・損耗・勝敗は手動時と同じルールです。</p><button id="confirmDelegate" class="primary">委任して解決</button><button id="cancelDelegate">戦術盤へ戻る</button>');$('#closeModal').hidden=true;$('#cancelDelegate').onclick=showBattle;$('#confirmDelegate').onclick=()=>{fieldBattle=B.auto(fieldBattle);showBattle();};};
}
dialog.addEventListener('cancel',ev=>{if(monthTransaction){ev.preventDefault();notify('合戦を解決して月末へ進めてください。中断時は出陣前の記録から再開できます。');}});

function talkDialog(q,back){
 const T=YabouDialogue,reason=E.canIssueCommand(state,q,R),o=state.officers.find(o=>o.id===q.targetId),a=state.officers.find(o=>o.id===q.officerId),line=T.preview(state,q);if(!o||!a||!line)return;
 modal(`<section class="talkScreen"><div class="talkHeading"><span class="eyebrow">${q.type==='hire'?'仕官の話':'ねぎらいの言葉'}</span><h2>${e(o.name)}と話す</h2></div><p class="talkSpeaker">${e(o.species||o.role)}／担当：${e(a.name)}</p><blockquote class="talkQuote">${e(line.text)}</blockquote><p class="talkTerms">${q.type==='hire'?'待遇金 '+q.offer+'。成否は月末の交渉で確定し、失敗しても待遇金を消費します。':'褒賞金 '+q.offer+'／忠誠 +'+Math.min(100-o.loyalty,YabouLoyalty.rewards[q.offer])+'。効果は月末に確定します。'}</p><p class="muted">話を聞くだけでは費用・任務を消費しません。予約後は既存の城2命令・武将1任務の制限が適用され、月末まで取消できます。</p><div class="talkActions"><button class="primary" id="queueTalk" ${reason?'disabled':''}>${q.type==='hire'?'この条件で交渉を予約':'この褒賞を予約'}</button><button id="backTalk">条件の選択に戻る</button></div>${reason?'<p class="notice">'+e(reason)+'</p>':''}</section>`);
 $('#backTalk').onclick=back;$('#queueTalk').onclick=()=>{try{state=E.queueCommand(state,q,R);dialog.close();render();notify(q.type==='hire'?'登用交渉を予約しました。返答は月末に届きます':'褒賞を予約しました。返答は月末に届きます');}catch(err){notify(err.message);}};
}
function dialogueHistoryDialog(){
 const T=YabouDialogue,SIZE=8,rows=state.personnel.dialogue.history.filter(h=>h.factionId===state.playerFactionId).slice().reverse(),names=[...new Set(rows.map(h=>h.officerId))],labels={hireAccepted:'仕官を承諾',hireRefused:'仕官を辞退',rewardReceived:'褒賞への返答',marchDeparture:'出発の言葉',battleWon:'戦勝の言葉',battleLost:'敗戦の言葉',diplomacySuccess:'外交成立の復命',diplomacyRefused:'外交不成立の復命',diplomacyCancelled:'交渉中止の復命',offerAccepted:'届いた提案を受諾',offerDeclined:'届いた提案を辞退'},groups={hire:'登用',reward:'褒賞',march:'出発',battle:'戦後',diplomacy:'外交使節',offer:'届いた提案'};
 const officer=id=>state.officers.find(o=>o.id===id)?.name||'',castle=id=>state.castles.find(c=>c.id===id)?.name||'',group=h=>Object.keys(groups).find(k=>h.scene.startsWith(k)),normalize=x=>x.normalize('NFKC').toLocaleLowerCase('ja');let page=0;
 modal(`<section class="talkHistoryScreen"><h2>武将との会話記録</h2><p class="muted">実行した会話を最新${T.LIMIT}件まで保存。閲覧だけの助言や、旧セーブに残らない過去の言葉は追加しません。</p><div class="talkHistoryControls"><label>武将<select id="talkHistoryOfficer"><option value="all">全員</option>${names.map(id=>`<option value="${id}">${e(officer(id))}</option>`).join('')}</select></label><label>場面<select id="talkHistoryKind"><option value="all">すべての場面</option>${Object.entries(groups).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label class="talkHistorySearch">キーワード<input id="talkHistorySearch" type="search" maxlength="60" placeholder="台詞・武将・城・勢力" autocomplete="off"></label></div><div class="talkHistoryToolbar"><div class="talkHistorySummary"><p id="talkHistoryCount" role="status" aria-live="polite"></p><button id="talkHistoryReset">絞り込みを解除</button></div><nav class="talkHistoryPages" aria-label="会話記録のページ"></nav></div><div id="talkHistoryList"></div><nav class="talkHistoryPages" aria-label="会話記録のページ（末尾）"></nav></section>`);
 const draw=()=>{const who=$('#talkHistoryOfficer').value,kind=$('#talkHistoryKind').value,word=normalize($('#talkHistorySearch').value.trim()),matches=rows.filter(h=>(who==='all'||h.officerId===who)&&(kind==='all'||group(h)===kind)&&(!word||normalize([officer(h.officerId),officer(h.actorId),h.text,labels[h.scene],castle(h.castleId),castle(h.targetCastleId),h.otherFactionId?faction(h.otherFactionId).name:''].join(' ')).includes(word))),pages=Math.max(1,Math.ceil(matches.length/SIZE));page=Math.min(page,pages-1);
  $('#talkHistoryCount').textContent=matches.length+' / '+rows.length+'件'+(matches.length?'・'+(page*SIZE+1)+'〜'+Math.min((page+1)*SIZE,matches.length)+'件目':'');$('#talkHistoryReset').disabled=who==='all'&&kind==='all'&&!$('#talkHistorySearch').value;
  document.querySelectorAll('.talkHistoryPages').forEach(nav=>{nav.innerHTML=`<button data-talk-page="prev" ${page===0?'disabled':''}>前へ</button><span>${page+1} / ${pages}ページ</span><button data-talk-page="next" ${page+1>=pages?'disabled':''}>次へ</button>`;nav.hidden=matches.length===0;});
  $('#talkHistoryList').innerHTML=matches.slice(page*SIZE,(page+1)*SIZE).map(h=>`<article class="talkHistoryItem" data-talk-id="${e(h.id)}"><small>第${Math.floor((h.turn-1)/12)+1}年 ${(h.turn-1)%12+1}月／${labels[h.scene]}／${e(castle(h.castleId))}${h.targetCastleId?' → '+e(castle(h.targetCastleId)):''}${h.diplomacyType?'／'+e(YabouDiplomacy.labels[h.diplomacyType])+'・'+e(faction(h.otherFactionId).name):''}</small><h3>${e(officer(h.officerId))}</h3><blockquote class="talkQuote">${e(h.text)}</blockquote><button data-talk-biography="${h.officerId}">列伝を読む</button></article>`).join('')||'<p class="notice">'+(rows.length?'条件に合う会話がありません。絞り込みを解除すると、保存されている記録を表示します。':'まだ実行した会話の記録はありません。')+'</p>';
  document.querySelectorAll('[data-talk-biography]').forEach(b=>b.onclick=()=>biographyDialog(b.dataset.talkBiography));document.querySelectorAll('[data-talk-page]').forEach(b=>b.onclick=()=>{page+=b.dataset.talkPage==='next'?1:-1;draw();$('#dialogContent').scrollTop=0;});
 };
 const filter=()=>{page=0;draw();};$('#talkHistoryOfficer').onchange=filter;$('#talkHistoryKind').onchange=filter;$('#talkHistorySearch').oninput=filter;$('#talkHistoryReset').onclick=()=>{$('#talkHistoryOfficer').value='all';$('#talkHistoryKind').value='all';$('#talkHistorySearch').value='';filter();};draw();
}

function personnelDialog(){const c=state.castles.find(c=>c.id===selected);if(c.ownerFactionId!==state.playerFactionId){notify('自領の城を選んでください');return;}const os=state.officers.filter(o=>o.status==='active'&&o.factionId===state.playerFactionId&&o.locationCastleId===c.id);const known=state.officers.filter(o=>o.status==='ronin'&&(state.personnel.known[state.playerFactionId]||[]).includes(o.id));modal(`<h2>探索・登用 / ${e(c.name)}</h2><p>1城2命令・武将1任務を共有。発見と登用は別の月です。</p><label>担当 <select id="personOfficer">${os.map(o=>'<option value="'+o.id+'">'+e(o.name)+'</option>').join('')}</select></label><label>探索規模 <select id="searchMode"><option value="careful">慎重 100金</option><option value="normal" selected>通常 250金</option><option value="large">大規模 500金</option></select></label><button id="queueSearch">探索を予約</button><h3>発見済みの浪人</h3><label>待遇金 <input id="hireOffer" type="number" min="0" max="300" value="100"></label>${known.map(o=>'<p>'+e(o.name)+' / '+e(o.species||'浪人')+' / 政治 '+o.stats.politics+' <button data-hire="'+o.id+'">登用交渉</button> <button data-hire-talk="'+o.id+'">話を聞く</button></p>').join('')||'<p>まだ見つかっていません。</p>'}<button id="dialogueHistory">会話の記録を読む</button><h3>最近の人材報告</h3>${state.personnel.log.filter(x=>x.factionId===state.playerFactionId).slice(-8).reverse().map(x=>'<p>第'+x.turn+'月：'+e(x.text)+'</p>').join('')||'<p>記録なし</p>'}`);const hireQuery=targetId=>({type:'hire',targetId,offer:Number($('#hireOffer').value),castleId:c.id,officerId:$('#personOfficer').value,factionId:state.playerFactionId});$('#dialogueHistory').onclick=dialogueHistoryDialog;document.querySelectorAll('[data-hire-talk]').forEach(b=>b.onclick=()=>{const q=hireQuery(b.dataset.hireTalk);talkDialog(q,()=>{personnelDialog();$('#personOfficer').value=q.officerId;$('#hireOffer').value=q.offer;});});const queue=q=>{try{state=E.queueCommand(state,{...q,castleId:c.id,officerId:$('#personOfficer').value,factionId:state.playerFactionId},R);dialog.close();render();notify('人材命令を予約しました');}catch(err){notify(err.message);}};$('#queueSearch').onclick=()=>queue({type:'search',mode:$('#searchMode').value});document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>queue({type:'hire',targetId:b.dataset.hire,offer:Number($('#hireOffer').value)}));}
function loyaltyDialog(){
 const c=state.castles.find(c=>c.id===selected);
 if(c.ownerFactionId!==state.playerFactionId){notify('自領の城を選んでください');return;}
 const os=state.officers.filter(o=>o.status==='active'&&o.factionId===state.playerFactionId&&o.locationCastleId===c.id);
 modal(`<section class="loyaltyScreen"><h2>家臣の忠誠・関係 / ${e(c.name)}</h2>
  <p class="muted loyaltyHint">月末確定・城2命令枠・担当1任務枠。月末まで取消できます。</p>
  <div class="loyaltyControls"><label>担当者 <select id="loyaltyOfficer">${os.map(o=>`<option value="${o.id}">${e(o.name)}</option>`).join('')}</select></label>
  <label>褒賞額 <select id="rewardOffer"><option value="100">100金 / 忠誠 +5</option><option value="250">250金 / 忠誠 +10</option><option value="500">500金 / 忠誠 +18</option></select></label></div>

  <div id="loyaltyRoster"></div>
  <details><summary>忠誠の目安と変化</summary><p>忠臣 80〜100 / 安定 60〜79 / 不満 40〜59 / 危険 20〜39 / 深刻 0〜19。褒賞で担当者との関係が3上がります。</p><p>兵糧不足で毎月 −3（義理80以上は −2）、民心40未満で −1。3・6・9・12月に、兵糧が足りて民心70以上なら +1。忠誠は0〜100で保たれます。</p></details>
  <button id="dialogueHistory">会話の記録を読む</button><h3>最近の人材報告</h3>${state.personnel.log.filter(x=>x.factionId===state.playerFactionId).slice(-10).reverse().map(x=>`<p>第${Math.floor((x.turn-1)/12)+1}年 ${(x.turn-1)%12+1}月：${e(x.text)}</p>`).join('')||'<p>記録なし</p>'}</section>`);
 $('#dialogueHistory').onclick=dialogueHistoryDialog;const query=targetId=>({type:'reward',castleId:c.id,officerId:$('#loyaltyOfficer').value,targetId,offer:Number($('#rewardOffer').value),factionId:state.playerFactionId});
 function roster(){
  const actor=$('#loyaltyOfficer').value;
  $('#loyaltyRoster').innerHTML=os.filter(o=>o.role!=='大名').map(o=>{const q=query(o.id),reason=E.canIssueCommand(state,q,R),gain=Math.min(100-o.loyalty,YabouLoyalty.rewards[q.offer]);return `<section class="loyaltyRow ${o.loyalty<60?'loyaltyConcern':''}">
   <div><strong>${e(o.name)}</strong> <span>${e(o.role)}</span><p>忠誠 <b>${o.loyalty}</b> / ${E.loyaltyLabel(o.loyalty)}</p><meter min="0" max="100" value="${o.loyalty}" aria-label="${e(o.name)}の忠誠">${o.loyalty}</meter>
   <p class="muted">義理 ${o.duty??50} / 野心 ${o.ambition??50} / 担当者との関係 ${actor===o.id?'本人':E.bond(state,actor,o.id)}</p></div>
   <div><button data-reward-target="${o.id}" ${reason?'disabled':''}>${e(o.name)}に褒賞</button><small>${e(reason||('忠誠 +'+gain+' / 金'+q.offer))}</small><button data-reward-talk="${o.id}" ${reason?'disabled':''}>話を聞く</button></div></section>`;}).join('')||'<p>この城に配置された武将はいません。</p>';
  document.querySelectorAll('[data-reward-talk]').forEach(b=>b.onclick=()=>{const q=query(b.dataset.rewardTalk);talkDialog(q,()=>{loyaltyDialog();$('#loyaltyOfficer').value=q.officerId;$('#rewardOffer').value=q.offer;$('#rewardOffer').dispatchEvent(new Event('change'));});});document.querySelectorAll('[data-reward-target]').forEach(b=>b.onclick=()=>{try{state=E.queueCommand(state,query(b.dataset.rewardTarget),R);dialog.close();render();notify('褒賞を予約しました。忠誠の変化は月末に確定します');}catch(err){notify(err.message);}});
 }
 $('#loyaltyOfficer').onchange=roster;$('#rewardOffer').onchange=roster;roster();
}
function showEvents(){
 if(state.personnel.chains.pending){chainsDialog();return;}

 if(state.personnel.drama.pending){dramaDialog();return;}

 const X=YabouEvents,p=state.events.pending,d=p?X.byId[p.id]:null,history=state.events.history.slice(-12).reverse().sort((a,b)=>Number(b.followupTurn===state.turn)-Number(a.followupTurn===state.turn));
 const date=t=>`第${Math.floor((t-1)/12)+1}年 ${(t-1)%12+1}月`;
 modal(`<section class="eventScreen"><h2>${d?e(d.title):'出来事の記録'}</h2>
  ${p?`<p class="muted">${e(state.castles.find(c=>c.id===p.castleId).name)} / ${date(p.turn)}${d.rumor?' / 未確認の噂を含む':''}</p>
  <p class="eventText">${e(d.text)}</p><div class="eventChoices">${X.options(state).map(c=>{const reason=X.canChoose(state,p.uid,c.id);return `<div><button data-event-choice="${c.id}" ${reason?'disabled':''}>${e(c.label)}</button><p class="muted">${e(X.preview(state,c))}</p>${reason?`<p role="status">${e(reason)}</p>`:''}</div>`;}).join('')}</div>
  <button id="dismissEvent">今回は判断を見送る</button><p class="muted"><small>閉じても今月中は選べます。次月へ進むと未選択の出来事は見送りになり、追加の費用・報酬は発生しません。</small></p>`:'<p>今月、新しく判断する出来事はありません。</p>'}
  <button id="chainStories">連鎖の物語</button><button id="dramaHistory">家臣の便りを読む</button><h3>最近の出来事・後日談</h3>${history.map(h=>`<details ${h===history[0]||h.followupTurn===state.turn?'open':''}><summary>${h.followupTurn===state.turn?'新しい便り / ':''}${date(h.turn)} / ${e(X.byId[h.id].title)}</summary><p>${e(h.text)}</p>${h.followup?`<p class="eventAfter"><b>後日談 / ${date(h.followupTurn)}</b><br>${e(h.followup)}</p>`:h.choiceId!=='SKIP'?'<p class="muted">後の便りを待っています。</p>':''}</details>`).join('')||'<p class="muted">まだ記録はありません。</p>'}</section>`);
 $('#chainStories').onclick=chainsDialog;$('#dramaHistory').onclick=dramaDialog;
 if(!p)return;
 $('#dismissEvent').onclick=()=>{try{state=E.dismissEvent(state,p.uid,M,R);const saved=save();render();showEvents();if(saved)notify('この出来事の判断を見送りました');}catch(err){notify(err.message);}};
 document.querySelectorAll('[data-event-choice]').forEach(b=>b.onclick=()=>{
  try{const result=E.chooseEvent(state,p.uid,b.dataset.eventChoice,M,R);state=result.state;const saved=save();render();
   if(result.panel==='diplomacy')openDiplomacy();else if(result.panel==='military')openMilitary();else if(result.panel==='agriculture')commandDialog('cultivate',state.castles.find(c=>c.id===p.castleId));else showEvents();
   if(saved)notify('選択の結果を記録しました');
  }catch(err){notify(err.message);}
 });
}
