 modal('<section class="dramaScreen"><h2>'+e(p?Z.titles[p.kind]:'家臣の便り')+'</h2><button id="chainStories">連鎖の物語</button>'+(p?'<p class="muted">'+date(p.turn)+' / '+e(state.castles.find(c=>c.id===p.castleId).name)+'</p><p>'+e(Z.text(state,p))+'</p><div class="eventChoices">'+Z.options(p).map(c=>{const reason=Z.canChoose(state,p.uid,c.id);return '<div><button data-drama-choice="'+c.id+'" '+(reason?'disabled':'')+'>'+e(c.label)+'</button><p class="muted">'+e(Z.preview(c))+'</p>'+(reason?'<small>'+e(reason)+'</small>':'')+'</div>';}).join('')+'</div><button id="dismissDrama">今回は判断を見送る</button><p class="muted dramaHint">閉じても今月中は選べます。次月へ進むと見送りとなり、追加の費用や変化はありません。</p>':'<p class="dramaHint">今月の新しい申し出はありません。城内の交流や共闘をきっかけに、家臣から便りが届きます。</p>')+'<h3>最近の便り</h3>'+v.history.slice(-12).reverse().map((h,i)=>'<details '+(i===0?'open':'')+'><summary>'+date(h.turn)+' / '+e(Z.titles[h.kind])+(h.choiceId==='SKIP'?'（見送り）':'')+'</summary><p>'+e(h.text)+'</p></details>').join('')+(!v.history.length?'<p class="muted">まだ便りは届いていません。</p>':'')+'<details><summary>便りの頻度と扱い</summary><p>最大2か月に1件。同じ種類は12か月、同じ家臣は4か月間隔。通常の出来事がある月は優先します。重要な申し出は予兆の段階で届き、勝手に決闘や謀反へ進みません。能力値・所属・兵力は自動で変わりません。</p></details></section>');
